  const fIdCol = fcol.indexOf('id');
  const fFloorCol = fcol.indexOf('floor');
  const fModeCol = fcol.indexOf('mode');
  const fNCol = fcol.indexOf('n');
  const floorRows = eventsData.tables.floors.rows;
  const eps = c['noUpgrades.epsilon'];

  // правило 7: спуск на этаж глубже без улучшений
  function floorDownEvents(from, to, levels) {
    const out = [];
    if (to !== from + 1) return out;
    for (const l of levels) {
      if (l - 0 > eps) return out;
    }
    for (const row of floorRows) {
      const floor = row[fFloorCol];
      // «to не меньше floor» с эпсилоном (правило 1 spec challenges)
      if (!(to > floor || Math.abs(to - floor) <= eps)) continue;
      out.push({ id: row[fIdCol], mode: row[fModeCol], n: row[fNCol] });
    }
    return out;
  }

  return { fire, pause, isChainTick, chainTickEvents, autobombEvents, floorDownEvents };""")
